// update for the pipeline, this request is a no-op.
func (c *internalClient) Stop(ctx context.Context, req StopPipelineRequest, opts ...call.Option) (*StopWaiter, error) {
	if req.PipelineId == nil {
		return nil, fmt.Errorf("request field %q required for polling is missing", "PipelineId")
	}
	capturedPipelineId := *req.PipelineId
	_, err := c.stopBase(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	return &StopWaiter{
		poll:       c.Get,
		pipelineId: capturedPipelineId,
	}, nil
}

// StopWaiter tracks the state of the operation started by Stop.
type StopWaiter struct {
	poll       func(context.Context, GetPipelineRequest, ...call.Option) (*GetPipelineResponse, error)
	pipelineId string
}

// GetPipelineId returns the PipelineId value used to identify the operation.
func (w *StopWaiter) GetPipelineId() string {
	return w.pipelineId
}

// Done polls once and reports whether the operation has reached a terminal state.
func (w *StopWaiter) Done(ctx context.Context, opts ...call.Option) (bool, error) {
	pollResp, err := w.poll(ctx, GetPipelineRequest{
		PipelineId: &w.pipelineId,
	}, opts...)
	if err != nil {
		return false, err
	}
	if pollResp == nil {
		return false, fmt.Errorf("response is missing")
	}
	status := pollResp.State
	if status == "" {
		return false, fmt.Errorf("response missing required status field")
	}
	switch status {
	case PipelineState_PipelineState_Idle, PipelineState_PipelineState_Failed:
		return true, nil
	default:
		return false, nil
	}
}

// Wait polls until the operation reaches a terminal state.
func (w *StopWaiter) Wait(ctx context.Context, opts ...lro.Option) (*GetPipelineResponse, error) {
	var result *GetPipelineResponse
	poll := func(ctx context.Context) error {
		pollResp, err := w.poll(ctx, GetPipelineRequest{
			PipelineId: &w.pipelineId,
		})
		if err != nil {
			return err
		}
		if pollResp == nil {
			return fmt.Errorf("response is missing")
		}
		status := pollResp.State
		if status == "" {
			return fmt.Errorf("response missing required status field")
		}
		switch status {
		case PipelineState_PipelineState_Idle:
			result = pollResp
			return nil
		case PipelineState_PipelineState_Failed:
			message := "(no message)"
			if pollResp.Cause != nil {
				message = fmt.Sprintf("%v", *pollResp.Cause)
			}
			return fmt.Errorf("terminal state %s: %s", status, message)
		default:
			return errOperationStillRunning
		}
	}
	if err := executeWait(ctx, poll, opts...); err != nil {
		return nil, err
	}
	return result, nil
}
